  "sql": "SELECT\n  regions.name AS \"customers.regions.name\",\n  COUNT(*) AS \"customers.count_all\"\nFROM customers AS customers\nLEFT JOIN regions AS regions\n  ON customers.region_id = regions.id\nWHERE\n  CASE\n    WHEN customers.tags IS NULL OR ['vip', 'partner'] IS NULL\n    THEN NULL\n    ELSE LIST_HAS_ANY(\n      [__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL],\n      [__slayer_e FOR __slayer_e IN ['vip', 'partner'] IF __slayer_e IS NOT NULL]\n    )\n  END\nGROUP BY\n  regions.name\nORDER BY\n  \"customers.regions.name\" ASC\nLIMIT 101"
}
